const raw = $input.first().json;
const body = raw.body || raw;  // n8n sometimes wraps POST body under .body
const { category, content } = body;

let text = content;
let title = 'Untitled';
let tags = [];

// Strip YAML frontmatter and extract title + tags
const fmMatch = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
if (fmMatch) {
  const fm = fmMatch[1];
  text = fmMatch[2].trim();
  const titleMatch = fm.match(/^title:\s*(.+)$/m);
  if (titleMatch) title = titleMatch[1].replace(/['"]/g, '').trim();
  const tagsMatch = fm.match(/^tags:\s*\[([^\]]*)\]/m);
  if (tagsMatch) tags = tagsMatch[1].split(',').map(t => t.trim().replace(/['"]/g, ''));
}

// Chunk with overlap so context isn't lost at boundaries
const CHUNK_SIZE = 400;
const OVERLAP = 50;
const chunks = [];
let i = 0;
while (i < text.length) {
  chunks.push(text.slice(i, i + CHUNK_SIZE));
  if (i + CHUNK_SIZE >= text.length) break;
  i += CHUNK_SIZE - OVERLAP;
}

return [{ json: { title, category, tags, chunks, total: chunks.length } }];

const axios = require('axios');
const { title, category, tags, chunks } = $input.first().json;

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

// Create collection if it doesn't exist yet (idempotent)
try {
  await axios.put('http://qdrant:6333/collections/personal_knowledge', {
    vectors: { size: 768, distance: 'Cosine' }
  });
} catch(e) { /* already exists */ }

// Embed each chunk and build Qdrant points
const points = [];
for (let i = 0; i < chunks.length; i++) {
  const embedRes = await axios.post('http://ollama:11434/api/embeddings', {
    model: 'nomic-embed-text',
    prompt: chunks[i]
  });
  points.push({
    id: uuid(),
    vector: embedRes.data.embedding,
    payload: {
      text: chunks[i],
      title,
      category,
      tags,
      chunk_index: i,
      total_chunks: chunks.length,
      ingested_at: new Date().toISOString()
    }
  });
}

await axios.put('http://qdrant:6333/collections/personal_knowledge/points', { points });

return [{ json: { ok: true, title, chunks_stored: points.length } }];
